import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, color, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, DirectionalLight, DoubleSide } = ctx.THREE;
  const group = new Group();
  const disposables = [];
  const timelines = [];

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const byRole = (role) => items.filter((i) => i.role === role);
  const wordmarkItem = byRole('wordmark')[0];
  const headers = byRole('column-header');
  const links = byRole('link');
  const legalItem = byRole('legal')[0];

  // Backdrop stage plane
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();
  backdropMat.colorNode = mix(color('#0b0b10'), color('#121218'), smoothstep(0.0, 1.0, uv().y));
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  group.add(backdrop);
  disposables.push(backdropGeo, backdropMat);

  // Footer band
  const bandW = 6.8, bandH = 2.0;
  const band = new Group();
  group.add(band);

  const bandGeo = new PlaneGeometry(bandW, bandH);
  const bandMat = new MeshStandardNodeMaterial({ roughness: 0.6, metalness: 0.2, side: DoubleSide });
  bandMat.colorNode = mix(color('#0b0b10'), color('#121218'), uv().y);
  const bandMesh = new Mesh(bandGeo, bandMat);
  band.add(bandMesh);
  disposables.push(bandGeo, bandMat);

  // Hairline rules
  const hairGeo = new PlaneGeometry(bandW, 0.006);
  const hairMat = new MeshStandardNodeMaterial({ roughness: 0.35, metalness: 0.5 });
  hairMat.colorNode = color('#23232b');
  const topHair = new Mesh(hairGeo, hairMat);
  topHair.position.set(0, bandH / 2 - 0.003, 0.005);
  band.add(topHair);
  const legalHair = new Mesh(hairGeo, hairMat);
  legalHair.position.set(0, -bandH / 2 + 0.375 + 0.25, 0.005);
  band.add(legalHair);
  disposables.push(hairGeo, hairMat);

  // Key light grazing from upper left
  const key = new DirectionalLight('#e8ecf2', 1.1);
  key.position.set(-3, 3, 2);
  group.add(key);
  const rim = new DirectionalLight('#ff2a38', 0.5);
  rim.position.set(3, -1, 1.5);
  group.add(rim);

  const left = -bandW / 2 + 0.5;
  const top = bandH / 2 - 0.5;

  // Wordmark block
  if (wordmarkItem) {
    const wm = ctx.fontAtlas.createText(String(wordmarkItem.text), {
      fontSize: 34, color: '#e8ecf2', align: 'left', letterSpacingPx: 0.7,
    });
    wm.position.set(left, top, 0.01);
    band.add(wm);
  }
  const barGeo = new PlaneGeometry(0.3, 0.02);
  const barMat = new MeshStandardNodeMaterial({ emissive: 0xff2a38, emissiveIntensity: 1.4, roughness: 0.5 });
  barMat.colorNode = color('#ff2a38');
  const bar = new Mesh(barGeo, barMat);
  bar.position.set(left + 0.15, top - 0.35, 0.01);
  band.add(bar);
  disposables.push(barGeo, barMat);

  // Three link columns
  const colW = 1.2, gutter = 0.375;
  const colStartX = left + 2.0 + gutter;
  const linkGroups = [links.slice(0, 3), links.slice(3, 6), links.slice(6, 9)];
  const navTargets = {
    'Features': 'hub-features', 'Collection': 'hub-collection', 'Pricing': 'hub-pricing',
    'Journal': 'hub-journal', 'Visit the Atelier': 'hub-journal', 'Contact': 'hub-journal',
  };
  const hoverables = [];

  for (let c = 0; c < 3; c++) {
    const x = colStartX + c * (colW + gutter);
    const header = headers[c];
    if (header) {
      const h = ctx.fontAtlas.createText(String(header.text), {
        fontSize: 9, color: '#8a8f99', align: 'left', letterSpacingPx: 1.1,
      });
      h.position.set(x, top, 0.01);
      band.add(h);
    }
    (linkGroups[c] || []).forEach((linkItem, i) => {
      const holder = new Group();
      const t = ctx.fontAtlas.createText(String(linkItem.text), {
        fontSize: 13, color: '#e8ecf2', align: 'left',
      });
      holder.add(t);
      holder.position.set(x, top - 0.25 - i * 0.25, 0.01);
      holder.userData.linkText = String(linkItem.text);
      band.add(holder);
      hoverables.push(holder);
    });
  }

  // Legal line
  if (legalItem) {
    const legal = ctx.fontAtlas.createText(String(legalItem.text), {
      fontSize: 9, color: '#8a8f99', align: 'left', letterSpacingPx: 0.4,
    });
    legal.position.set(left, -bandH / 2 + 0.375 - 0.05, 0.01);
    band.add(legal);
  }

  // Mount fade-up
  band.position.y = -0.2;
  const mountTl = gsap.timeline();
  mountTl.to(band.position, { y: 0, duration: 0.5, ease: 'power2.out' });
  timelines.push(mountTl);

  // Hover / click handlers
  group.userData.handlers = {
    pointermove: (hit) => {
      for (const h of hoverables) {
        const isHit = hit && (hit === h || (hit.parent && hit.parent === h) || h.children.includes(hit));
        const target = isHit ? 0.02 : 0;
        if (Math.abs(h.position.z - 0.01 - target) > 0.001) {
          gsap.to(h.position, { z: 0.01 + target, duration: 0.14, ease: 'power2.out' });
        }
      }
    },
    click: (hit) => {
      let node = hit;
      while (node && !node.userData?.linkText) node = node.parent;
      if (node) {
        gsap.to(node.scale, { x: 0.97, y: 0.97, duration: 0.12, yoyo: true, repeat: 1, ease: 'back.out' });
        const to = navTargets[node.userData.linkText];
        if (to) ctx.emit('navigate', { to });
      }
    },
  };

  group.userData.cleanup = () => {
    timelines.forEach((t) => t.kill());
    gsap.killTweensOf(band.position);
    hoverables.forEach((h) => { gsap.killTweensOf(h.position); gsap.killTweensOf(h.scale); });
    disposables.forEach((d) => d.dispose && d.dispose());
  };

  return group;
}
